import type { MultiSelectContentProps } from "../multi-select.types";

import React, { forwardRef } from "react";
import { Menu } from "@components/menu";

import { MultiSelectClasses, StyledMultiSelect } from "../multi-select.styles";
import { useMultiSelect } from "../hooks/use-multi-select";

export const MultiSelectContent = forwardRef<HTMLDivElement, MultiSelectContentProps>(
  ({ children, ...props }, ref) => {
    const {
      triggerWidth,
      contentRef,
      "aria-labelledby": ariaLabelledBy,
      theme,
      variant,
      styleSlots,
      isOpening,
      isOutsideClick,
    } = useMultiSelect();

    const hasLabel = ariaLabelledBy || props["aria-label"] || props["aria-labelledby"];

    return (
      <Menu.Content
        ref={(node) => {
          if (typeof ref === "function") {
            ref(node);
          } else if (ref) {
            ref.current = node;
          }
          (contentRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        aria-label={hasLabel ? undefined : "Options"}
        aria-labelledby={ariaLabelledBy}
        aria-orientation={undefined}
        collisionPadding={10}
        isOpening={isOpening}
        role="dialog"
        style={{
          width: triggerWidth ? `${triggerWidth}px` : "auto",
          ...props.style,
        }}
        onCloseAutoFocus={(e) => {
          if (isOutsideClick.current) {
            e.preventDefault();
            isOutsideClick.current = false;
          }
        }}
        onPointerDownOutside={() => {
          isOutsideClick.current = true;
        }}
        {...props}
      >
        <Menu.Group>
          <StyledMultiSelect
            className={MultiSelectClasses.content}
            currentTheme={theme}
            styleSlots={styleSlots}
            variant={variant}
          >
            {children}
          </StyledMultiSelect>
        </Menu.Group>
      </Menu.Content>
    );
  },
);
MultiSelectContent.displayName = "MultiSelect.Content";
